(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.Charts=factory();})(globalThis,function(){
'use strict';const colors=['#4654ed','#8b5cf6','#ef9645','#138da1','#d55f80','#637590'];const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const color=i=>colors[i%colors.length];
function svg(body,label,w=700,h=220){return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}">${body}</svg>`;}
function cost(rows,{money,t,selected}){if(!rows.length)return `<div class="chart-empty">${t('No eligible quotes to chart. Review the quotation gaps.','暂无可绘制的合格报价，请先检查报价问题。')}</div>`;const max=Math.max(1,...rows.map(r=>r.total)),h=rows.length*54+52;let body='';for(let i=0;i<=4;i++){const x=148+i*117;body+=`<line x1="${x}" y1="12" x2="${x}" y2="${h-28}" class="grid-line"/><text x="${x}" y="${h-9}" text-anchor="middle" class="axis-text">${esc(money(max*i/4))}</text>`;}rows.forEach((r,i)=>{let x=148;const y=i*54+24;body+=`<g class="chart-hit ${selected===r.q.id?'is-selected':''}" tabindex="0" role="button" data-action="inspect" data-id="${esc(r.q.id)}" aria-label="${esc(r.q.name+': '+money(r.total))}"><title>${esc(r.q.name)}: ${esc(money(r.total))}</title><text x="137" y="${y+19}" text-anchor="end" class="chart-label">${esc(r.q.name.length>20?r.q.name.slice(0,18)+'…':r.q.name)}</text>`;[[r.net,'#4654ed',t('Items','商品')],[r.shippingAmount,'#aaa5fa',t('Shipping','运费')],[r.feesAmount,'#94c9df',t('Fees','费用')],[r.taxAmount,'#f9a75e',t('Tax','税额')]].forEach(([v,c,l])=>{const width=v/max*468;body+=`<rect x="${x}" y="${y}" width="${width}" height="30" fill="${c}"><title>${esc(l)}: ${esc(money(v))}</title></rect>`;x+=width;});body+=`<text x="${Math.min(x+9,628)}" y="${y+19}" class="chart-value">${esc(money(r.total))}</text></g>`;});const mobile=`<div class="mobile-cost">${rows.map(r=>`<button type="button" class="mobile-cost-row" data-action="inspect" data-id="${esc(r.q.id)}"><span><b>${esc(r.q.name)}</b><strong>${esc(money(r.total))}</strong></span><span class="mobile-cost-bar" style="width:${Math.max(1,r.total/max*100)}%">${[[r.net,'#4654ed'],[r.shippingAmount,'#aaa5fa'],[r.feesAmount,'#94c9df'],[r.taxAmount,'#f9a75e']].map(([v,c])=>`<i style="width:${r.total?v/r.total*100:0}%;background:${c}"></i>`).join('')}</span></button>`).join('')}</div>`;return mobile+'<div class="desktop-cost">'+svg(body,t('Landed cost breakdown. Select a supplier for details.','到手成本构成。选择供应商查看明细。'),730,h)+'</div>'+`<div class="chart-legend">${[['#4654ed',t('Items after discount, ex tax','折后商品（税前）')],['#aaa5fa',t('Shipping','运费')],['#94c9df',t('Other fees','其他费用')],['#f9a75e',t('Tax','税额')]].map(([c,l])=>`<span><i style="background:${c}"></i>${l}</span>`).join('')}</div>`;}
function scatter(rows,{money,t}){const known=rows.filter(r=>r.q.days!==''&&r.q.days!==null);if(!known.length)return `<p class="muted">${t('No eligible quotes with known delivery estimates.','没有交期已知的合格报价。')}</p>`;const maxX=Math.max(1,...known.map(r=>Number(r.q.days)))*1.2,maxY=Math.max(1,...known.map(r=>r.total))*1.15;let b='';for(let i=0;i<=4;i++){const x=65+i*80,y=180-i*37;b+=`<line x1="65" y1="${y}" x2="385" y2="${y}" class="grid-line"/><text x="57" y="${y+4}" text-anchor="end" class="axis-text">${esc(money(maxY*i/4))}</text><text x="${x}" y="199" text-anchor="middle" class="axis-text">${(maxX*i/4).toFixed(1)}</text>`;}known.forEach((r,i)=>{const x=65+Number(r.q.days)/maxX*320,y=180-r.total/maxY*148;b+=`<g class="chart-hit" tabindex="0" role="button" data-action="inspect" data-id="${esc(r.q.id)}" aria-label="${esc(r.q.name)}, ${r.q.days} ${t('days','天')}, ${esc(money(r.total))}"><circle cx="${x}" cy="${y}" r="7" fill="${color(i)}" stroke="white" stroke-width="2"/><title>${esc(r.q.name)} · ${r.q.days} ${t('days','天')} · ${esc(money(r.total))}</title><text x="${Math.min(x+10,305)}" y="${y-10}" class="point-label">${esc(r.q.name.length>16?r.q.name.slice(0,14)+'…':r.q.name)}</text></g>`;});b+=`<text x="225" y="224" text-anchor="middle" class="axis-text">${t('Quoted delivery (calendar days) →','报价交期（日历天）→')}</text>`;return svg(b,t('Cost versus quoted delivery. Lower and left is better.','成本与报价交期，越靠左下越好。'),430,235)+`<div class="chart-legend scatter-legend">${known.map((r,i)=>`<span><i style="background:${color(i)}"></i>${esc(r.q.name)}</span>`).join('')}</div>`;}
function sensitivity(rows,steps,{t,current}){let b='';for(let i=0;i<=4;i++){const y=180-i*37,x=47+i*84;b+=`<line x1="47" y1="${y}" x2="383" y2="${y}" class="grid-line"/><text x="37" y="${y+4}" text-anchor="end" class="axis-text">${i*25}</text><text x="${x}" y="200" text-anchor="middle" class="axis-text">${i*25}</text>`;}const curr=47+current/100*336;b+=`<line x1="${curr}" y1="23" x2="${curr}" y2="180" stroke="#8893aa" stroke-dasharray="4 4"/>`;rows.forEach((r,i)=>{let segments=[],part=[];steps.forEach(s=>{const v=s.scores[r.q.id];if(v===null||v===undefined){if(part.length)segments.push(part);part=[];}else part.push(`${47+s.cost/100*336},${180-v/100*148}`);});if(part.length)segments.push(part);for(const segment of segments)b+=`<polyline points="${segment.join(' ')}" fill="none" stroke="${color(i)}" stroke-width="2.3"><title>${esc(r.q.name)}</title></polyline>`;});b+=`<text x="215" y="225" text-anchor="middle" class="axis-text">${t('Cost priority (%) →','成本权重 (%) →')}</text>`;return svg(b,t('Supplier score as cost priority changes','成本权重变化时的供应商得分'),430,235)+`<div class="chart-legend">${rows.map((r,i)=>`<span><i style="background:${color(i)}"></i>${esc(r.q.name)}</span>`).join('')}</div>`;}
function history(rows,{t}){return rows.map(r=>`<div class="history-row"><div><b>${esc(r.q.name)}</b><small>${r.reliability?.kind==='observed'?`${r.q.historyOnTime} / ${r.q.historyOrders} ${t('orders on time','笔订单准时')}`:t('No historical delivery records','暂无历史交付记录')}</small></div><div class="history-track"><span style="width:${r.reliability?.kind==='observed'?r.reliability.value:0}%"></span></div><b>${r.reliability?.kind==='observed'?r.reliability.value.toFixed(1)+'%':'—'}</b></div>`).join('');}
return {cost,scatter,sensitivity,history,color};});
